#!/bin/sh
# generated by neige-calm (a kernel gate or a gate run); do not edit
read -r _go || exit 75
if [ -n "${NEIGE_GATE_LOG_PATH:-}" ]; then exec >>"$NEIGE_GATE_LOG_PATH" 2>&1; fi
unset NEIGE_GATE_LOG_PATH
neige_gate_exit_path=$NEIGE_GATE_EXIT_PATH
unset NEIGE_GATE_EXIT_PATH
neige_gate_step_path=$NEIGE_GATE_STEP_PATH
unset NEIGE_GATE_STEP_PATH
neige_gate_finish() {
  printf '%s\n' "$1" > "$neige_gate_exit_path.tmp" && mv -f -- "$neige_gate_exit_path.tmp" "$neige_gate_exit_path"
  exit "$1"
}
printf '%s\n' 1 > "$neige_gate_step_path"
printf '%s\n' '::gate-step build '\''quoted'\'''
(
printf 'hello\n'
exit 0
)
neige_gate_rc=$?
if [ "$neige_gate_rc" -ne 0 ]; then neige_gate_finish "$neige_gate_rc"; fi
printf '%s\n' 2 > "$neige_gate_step_path"
printf '%s\n' '::gate-step verify'
(
test 1 = 1
)
neige_gate_rc=$?
if [ "$neige_gate_rc" -ne 0 ]; then neige_gate_finish "$neige_gate_rc"; fi
neige_gate_finish 0
